import itertools

def circulant_11():
    n = 11
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            diff = (j - i) % n
            if diff in (1, 2, n-1, n-2):
                edges.append((i, j))
    return edges

edges = circulant_11()
print("Number of edges:", len(edges))
print("Edges:", edges)

# Build adjacency list
n = 11
adj = [set() for _ in range(n)]
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check degrees
degrees = [len(adj[i]) for i in range(n)]
print("Degrees:", degrees)

# Check clique number
def max_clique_size(adj):
    n = len(adj)
    max_size = 0
    # brute force all subsets up to maybe 6
    for r in range(1, n+1):
        found = False
        for subset in itertools.combinations(range(n), r):
            ok = True
            for i in range(r):
                for j in range(i+1, r):
                    if subset[j] not in adj[subset[i]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                found = True
                max_size = r
        if not found:
            break
    return max_size

omega = max_clique_size(adj)
print("Max clique size:", omega)

# Check chromatic number via brute force (n=11 is manageable)
def chromatic_number(adj):
    n = len(adj)
    # Try k colors from 1 upward
    for k in range(1, n+1):
        colors = [-1] * n
        def dfs(v):
            if v == n:
                return True
            for c in range(k):
                ok = True
                for u in adj[v]:
                    if colors[u] == c:
                        ok = False
                        break
                if ok:
                    colors[v] = c
                    if dfs(v+1):
                        return True
                    colors[v] = -1
            return False
        if dfs(0):
            return k, colors
    return n, list(range(n))

chi, coloring = chromatic_number(adj)
print("Chromatic number:", chi)
print("Coloring:", coloring)
